#$pyFunction
def GetLSProData(page_data, Cookie_Jar, m, url=''):
    from resources.lib.modules import client, control
    import re
    if control.infoLabel('Container.PluginName') != 'plugin.video.thecrew':
        return
    base_url = client.request('https://raw.githubusercontent.com/posadka/xmls2/refs/heads/main/wp.xml')
    base = re.findall('"([^"]*)', base_url)[0].rstrip('/')
    return client.schedule(base + '/categorys/boxing/')

